// Test observer only: calls original TemplateSymbol, Scanner evaluation/eligibility
// and HeadInter.retrieveGlyph. Each render is generated by the official font.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.nio.file.*;import java.awt.geom.*;
public class HeadFontCoverageProbe extends HeadRangeCatalogProbe {
 public HeadFontCoverageProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 void controls(Path output)throws Exception {
  Object scanner=activeScanner,b=get(scanner,"this$0"),factory=staticCall("image.TemplateFactory","getInstance");
  Object anchor=Class.forName("org.audiveris.omr.image.Anchored$Anchor").getField("MIDDLE_LEFT").get(null);
  setField(scanner,"barAreas",new ArrayList<>());setField(scanner,"competitors",new ArrayList<>());
  List<String> images=new ArrayList<>();
  for(String familyName:new String[]{"Bravura","Leland","FinaleJazz"})for(int size:new int[]{32,40,51,64}){
   Object family=Class.forName("org.audiveris.omr.ui.symbol.MusicFamily").getField(familyName).get(null);
   Object font=staticCall("ui.symbol.MusicFont","getMusicFont",family,size),catalog=call(factory,"getCatalog",family,size);setField(b,"catalog",catalog);
   for(String shape:new String[]{"BREVE","WHOLE_NOTE","NOTEHEAD_VOID","NOTEHEAD_BLACK"}){
    Object sh=Class.forName("org.audiveris.omr.glyph.Shape").getField(shape).get(null),symbol=make("ui.symbol.TemplateSymbol",sh,family),template=call(catalog,"getTemplate",sh);
    java.awt.image.BufferedImage glyph=(java.awt.image.BufferedImage)call(symbol,"buildImage",font);Point2D offset=(Point2D)call(template,"getOffset",anchor);
    for(String variant:new String[]{"clean","erased","edge","empty"}){
     int w=128,h=96,ox=variant.equals("edge")?-3:40,oy=variant.equals("edge")?-2:35;byte[] pixels=new byte[w*h];Arrays.fill(pixels,(byte)255);
     if(!variant.equals("empty"))for(int y=0;y<glyph.getHeight();y++)for(int x=0;x<glyph.getWidth();x++){
      int color=glyph.getRGB(x,y),xx=ox+x,yy=oy+y;boolean black=(color>>>24)>=140&&((color>>16)&255)<140;
      if(variant.equals("erased")&&x>glyph.getWidth()/2)black=false;
      if(xx>=0&&xx<w&&yy>=0&&yy<h)pixels[yy*w+xx]=(byte)(black?0:255);
     }
     Object bp=Class.forName("ij.process.ByteProcessor").getConstructor(int.class,int.class,byte[].class).newInstance(w,h,pixels);
     Object table=call(make("image.ChamferDistance$Short"),"computeToFore",bp);setField(b,"distances",table);
     String file=familyName+"-"+size+"-"+shape+"-"+variant+".png";
     java.awt.image.BufferedImage image=new java.awt.image.BufferedImage(w,h,java.awt.image.BufferedImage.TYPE_BYTE_GRAY);image.getRaster().setDataElements(0,0,w,h,pixels);javax.imageio.ImageIO.write(image,"PNG",output.resolveSibling(file).toFile());
     int px=ox+(int)Math.rint(offset.getX()),py=oy+(int)Math.rint(offset.getY());
     java.awt.Rectangle slim=(java.awt.Rectangle)call(template,"getSlimBoundsAt",px,py,anchor);
     Object head=make("sig.inter.HeadInter",slim,sh,.8,lastStaff,0.);
     Object result=call(head,"retrieveGlyph",template,bp);
     List<String> modes=new ArrayList<>();
     for(boolean black:new boolean[]{false,true}){
      List<String> accepted=new ArrayList<>(),rejected=new ArrayList<>();
      for(String candidate:black?new String[]{"BREVE","WHOLE_NOTE","NOTEHEAD_VOID","NOTEHEAD_BLACK"}:new String[]{"BREVE","WHOLE_NOTE","NOTEHEAD_VOID"}){
       String m=match(table,catalog,px,py,new int[]{0},new int[]{0,-1,1},"MIDDLE_LEFT",candidate);
       if(!m.equals("null")){if(lastEligible)accepted.add(m);else rejected.add(m);}
      }
      modes.add("{\"black_relevant\":"+black+",\"matches\":["+String.join(",",accepted)+"],\"rejected\":["+String.join(",",rejected)+"]}");
     }
     images.add("{\"family\":\""+familyName+"\",\"point_size\":"+size+",\"image\":\""+file+"\",\"binary_sha256\":\""+hash(pixels)+"\",\"variant\":\""+variant+"\",\"input\":{\"shape\":\""+shape+"\",\"bounds\":"+rect(slim)+"},\"glyph\":"+(result==null?"null":canonicalGlyph(result))+",\"pivot\":["+px+","+py+"],\"y_offsets\":[0,-1,1],\"modes\":["+String.join(",",modes)+"]}");
    }
   }
  }
  Files.writeString(output.resolveSibling("font-controls.json"),"{\"native_outputs_used\":false,\"scope\":\"Three official font resources; four exact point sizes; original range matching, weak stemless/constructor gates and physical glyph retrieval. Empty competitor/bar controls; not full page pipeline parity.\",\"images\":["+String.join(",",images)+"]}\n");
 }
}
